/*
 * TAK.NZ nav-menu icons, traced from ATAK-CIV.
 *
 * This module is TAK.NZ-only and is deliberately a new file: upstream will never
 * create this path, so it cannot conflict on a sync. See
 * branding/atak-icons/README.md for icon selection and MAPPING.md for
 * provenance and per-icon notes. Attribution lives in NOTICE at the repo root -
 * these assets are GPL-3.0 from ATAK-CIV and shipping them requires it.
 *
 * Path data is generated from branding/atak-icons/svg-traced/*.svg. Each traced
 * SVG is a single `evenodd` path on a 0 0 24 24 viewBox, matching the Tabler
 * grid the rest of the nav bar uses. Regenerate with the tracers documented in
 * branding/atak-icons/README.md, then re-run the generator noted in this repo's
 * commit for this file - do not hand-edit the `d` strings below.
 *
 * `vite-svg-loader` was deliberately not used: it would mean editing
 * vite.config.ts and package.json, both of which are synced from upstream.
 *
 * The contract these components must satisfy is set by
 * api/web/src/components/CloudTAK/Menu/MenuItemCard.vue, which renders:
 *
 *     <component :is='icon' v-if='icon' :size='iconSize' :color='resolvedIconColor'
 *                stroke='1' class='menu-item-card__icon' />
 *
 * Notes on that contract as of upstream v13.70.0:
 *
 *  - `size` is 36 for the tiles layout and 32 otherwise, and maps to width and
 *    height.
 *  - `color` is currently always undefined, because no caller passes
 *    `icon-color`. When it is set we drive it through `style.color` rather than
 *    a `fill` attribute so `currentColor` keeps resolving.
 *  - `stroke` is declared as a prop purely so it is consumed. These icons are
 *    filled outlines, not strokes, so stroke width has no effect on them - but
 *    if the prop were left undeclared, `stroke="1"` would fall through onto the
 *    root <svg> as an invalid paint value.
 *  - `v-tooltip` and `title` are NOT passed to the icon; v13.70.0 moved both
 *    onto the wrapping div. Do not add handling for them.
 *  - `class` is intentionally allowed to fall through so the card's own styling
 *    still applies.
 */
import { h, markRaw } from 'vue';
import type { Component, FunctionalComponent } from 'vue';

interface NavIconProps {
    size?: number | string;
    color?: string;
    /** Accepted and ignored - see the note on the contract above. */
    stroke?: number | string;
}

function atakNavIcon(name: string, d: string): Component {
    const icon: FunctionalComponent<NavIconProps> = (props) => h('svg', {
        xmlns: 'http://www.w3.org/2000/svg',
        viewBox: '0 0 24 24',
        width: props.size ?? 24,
        height: props.size ?? 24,
        fill: 'currentColor',
        stroke: 'none',
        'aria-hidden': 'true',
        ...(props.color ? { style: { color: props.color } } : {})
    }, [
        h('path', { 'fill-rule': 'evenodd', d })
    ]);

    icon.props = ['size', 'color', 'stroke'];
    icon.displayName = name;

    // Upstream markRaw()s plugin menu icons; base items are not wrapped. Doing
    // it here keeps Vue from walking these components looking for reactivity.
    return markRaw(icon);
}

